// The signer's own EIP-712 code against viem (test/fixtures/viem-fixture.json, generated by
// scripts/make-viem-fixture.mjs with the frontend's viem): same domain separator, same order
// hashes, same digests, same cancel digests. And nothing but those two messages can be hashed.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as eip712 from '../src/eip712.mjs';
import { FIXTURE } from './support/helpers.mjs';

const { cancelDigest, domainSeparator, hashOrderComponents, orderDigest, SEAPORT_DOMAIN, TYPE_HASHES } = eip712;

const toComponents = (c) => ({
  ...c,
  offer: c.offer.map((i) => ({ ...i, identifierOrCriteria: BigInt(i.identifierOrCriteria), startAmount: BigInt(i.startAmount), endAmount: BigInt(i.endAmount) })),
  consideration: c.consideration.map((i) => ({ ...i, identifierOrCriteria: BigInt(i.identifierOrCriteria), startAmount: BigInt(i.startAmount), endAmount: BigInt(i.endAmount) })),
  startTime: BigInt(c.startTime),
  endTime: BigInt(c.endTime),
  salt: BigInt(c.salt),
  counter: BigInt(c.counter),
});

test('the Seaport 1.6 domain separator equals viem hashDomain', () => {
  assert.equal(domainSeparator(), FIXTURE.domainSeparator);
  assert.deepEqual({ ...SEAPORT_DOMAIN, chainId: Number(SEAPORT_DOMAIN.chainId) }, { ...FIXTURE.domain, verifyingContract: FIXTURE.domain.verifyingContract.toLowerCase() });
});

test("the type hashes are Seaport's own constants", () => {
  // From Seaport's ConsiderationConstants / the deployed contract's typehash derivation.
  assert.equal(TYPE_HASHES.OrderComponents, '0xfa445660b7e21515a59617fcd68910b487aa5808b8abda3d78bc85df364b2c2f');
  assert.equal(TYPE_HASHES.OfferItem, '0xa66999307ad1bb4fde44d13a5d710bd7718e0c87c1eef68a571629fbf5b93d02');
  assert.equal(TYPE_HASHES.ConsiderationItem, '0x42d81c6929ffdc4eb27a0808e40e82516ad42296c166065de7f812492304ff6e');
});

for (const o of FIXTURE.orders) {
  test(`order hash and digest equal viem for: ${o.name}`, () => {
    const c = toComponents(o.components);
    assert.equal(hashOrderComponents(c), o.orderHash);
    assert.deepEqual(orderDigest(c), { orderHash: o.orderHash, digest: o.digest });
  });
  test(`gasless-cancel digest equals viem for: ${o.name}`, () => {
    assert.equal(cancelDigest(o.orderHash), o.cancel.digest);
  });
}

test('a one-wei change anywhere changes the order hash', () => {
  const c = toComponents(FIXTURE.orders[1].components);
  const base = hashOrderComponents(c);
  const bumped = structuredClone(c);
  bumped.consideration[3].startAmount += 1n;
  assert.notEqual(hashOrderComponents(bumped), base);
});

test('the module takes no caller-supplied types, domain or primary type, and has no bulk-order path', () => {
  assert.deepEqual(Object.keys(eip712).sort(), ['SEAPORT_DOMAIN', 'TYPE_HASHES', 'cancelDigest', 'domainSeparator', 'hashOrderComponents', 'orderDigest']);
  assert.equal(domainSeparator.length, 0);
  assert.equal(orderDigest.length, 1);
  assert.equal(cancelDigest.length, 1);
  assert.ok(Object.isFrozen(SEAPORT_DOMAIN));
  assert.throws(() => { SEAPORT_DOMAIN.verifyingContract = '0x0000000000000000000000000000000000000000'; });
  // Extra fields (as a caller might try to smuggle in) do not change what is hashed.
  const c = toComponents(FIXTURE.orders[0].components);
  assert.equal(hashOrderComponents({ ...c, types: { Evil: [] }, primaryType: 'Evil', domain: {} }), FIXTURE.orders[0].orderHash);
});

test('malformed values are refused rather than coerced', () => {
  const c = toComponents(FIXTURE.orders[0].components);
  assert.throws(() => hashOrderComponents({ ...c, salt: 5 }), /uint256/);
  assert.throws(() => hashOrderComponents({ ...c, zoneHash: '0x00' }), /bytes32/);
  assert.throws(() => hashOrderComponents({ ...c, offerer: '0x1234' }), /address/);
  assert.throws(() => hashOrderComponents({ ...c, orderType: 256 }), /uint8/);
  assert.throws(() => cancelDigest('0x1234'), /32 bytes/);
});
